def checkout(ctx, body, *args):
    try:
        cart, customer, amount = body["cart_id"], body["customer_id"], int(body["amount_cents"])
    except (KeyError, TypeError, ValueError):
        return 400, {"error": "cart_id, customer_id and amount_cents are required"}
    from ordersvc import db, payclient, settings
    S = settings.S
    import secrets
    import traceback
    conn = db.conn()
    try:
        # Start a transaction
        with conn.transaction():
            # Check for existing paid order
            cur = conn.execute(
                "SELECT id FROM orders WHERE cart_id = %s AND customer_id = %s AND amount_cents = %s AND status = 'paid'",
                (cart, customer, amount))
            row = cur.fetchone()
            if row:
                oid = row[0]
                # Get the order details
                cur.execute(
                    f"SELECT id, cart_id, customer_id, amount_cents, currency, status, charge_id, refunded_cents, created_at FROM {S.table('orders')} WHERE id = %s",
                    (oid,))
                row = cur.fetchone()
                if row:
                    keys = ["id", "cart_id", "customer_id", "amount_cents", "currency", "status", "charge_id", "refunded_cents", "created_at"]
                    order = dict(zip(keys, row))
                    order["created_at"] = order["created_at"].isoformat()
                else:
                    # This should not happen
                    conn.rollback()
                    return 500, {"error": "internal"}
                # Commit the transaction and return
                conn.commit()
                return 200, {"order_id": oid, "charge_id": order["charge_id"], "status": "paid"}
            else:
                # No existing paid order, create a new order
                oid = "o-" + secrets.token_hex(4)
                conn.execute(
                    f"INSERT INTO {S.table('orders')} (id, cart_id, customer_id, amount_cents, currency, status, request_id) "
                    f"VALUES (%s, %s, %s, %s, %s, 'pending', %s)",
                    (oid, cart, customer, amount, S.currency, ctx.trace))
                conn.execute(f"INSERT INTO {S.table('order_events')} (order_id, kind, detail) VALUES (%s, %s, %s)", (oid, "created", ctx.trace))
                # Charge
                try:
                    ch = payclient.charge(ctx, amount, S.currency, {"order_id": oid, "cart_id": cart})
                except payclient.PayError as e:
                    conn.execute(f"UPDATE {S.table('orders')} SET status = %s WHERE id = %s", ("failed", oid))
                    conn.execute(f"INSERT INTO {S.table('order_events')} (order_id, kind, detail) VALUES (%s, %s, %s)", (oid, "failed", None))
                    conn.commit()
                    _log(event="charge_failed", order=oid, status=e.status)
                    return 402, {"error": "payment failed", "order_id": oid}
                # Mark paid
                conn.execute(f"UPDATE {S.table('orders')} SET status = 'paid', charge_id = %s WHERE id = %s", (ch["id"], oid))
                conn.execute(f"INSERT INTO {S.table('order_events')} (order_id, kind, detail) VALUES (%s, %s, %s)", (oid, "paid", ch["id"]))
                conn.commit()
                _log(event="checkout", order=oid, cart=cart, charge=ch["id"], trace=ctx.trace)
                return 200, {"order_id": oid, "charge_id": ch["id"], "status": "paid"}
    except Exception as e:
        conn.rollback()
        _log(event="error", detail=traceback.format_exc()[-500:])
        return 500, {"error": "internal"}"}

